#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# Issue #358 / A113 clause 3. State lives beside the repo, not in .env.
ENV_FILE="${ENV_FILE:-.xai-a113-wizard.env}"
RECORD_FILE="${RECORD_FILE:-xai-a113-clause3-record.md}"

TEAM_NAME="Patchyard Factory"
TEAM_ID="24472de3-304e-46ae-824b-2f99ffb3aed8"
TEAM_URL="https://console.x.ai/team/${TEAM_ID}"

# remote_root CMD... runs a single command as root on the control plane via
# the two-hop route (MacBook -> orchestrate -> factory). Commands with tricky
# quoting go through remote_root_stdin, which ships a script over stdin.
remote_root() {
  local cmd="sudo -n $*" q
  printf -v q '%q' "$cmd"
  ssh operator@example-controller "sudo -n -u conductor ssh conductor@factory.example.com $q"
}
remote_root_stdin() {  # reads the script to run (as root) from stdin
  ssh operator@example-controller "sudo -n -u conductor ssh conductor@factory.example.com 'sudo -n /bin/sh'"
}

banner "xAI Factory seat key (issue #358, A113 clause 3)"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Payment method on the Patchyard Factory team"
say "The dedicated team '${TEAM_NAME}' already exists (id ${TEAM_ID})"
say "with a \$0.00 credit balance. The postpaid spending limit is the"
say "provider-side money boundary, and postpaid needs a card on the team."
open_url "${TEAM_URL}/settings/billing"
step "Under 'Payment details', click 'Add payment method' and add the card."
step "Add billing details too if invoices should carry them."
warn "Do NOT add prepaid credits, and do NOT enable auto top-up: a team"
say "carrying prepaid credit fails A-5 (the postpaid limit isn't binding)."
pause "Press Enter once the card shows under Payment details."

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Low postpaid spending limit (via Management API)"
say "The console UI does not expose the invoiced/postpaid limit for this"
say "team (checked 2026-08-30), but the Management API does:"
note "POST https://management-api.x.ai/v1/billing/teams/<id>/postpaid/spending-limits"
open_url "${TEAM_URL}/settings/management-keys"
step "Create a management key for the Patchyard Factory team. Copy it."
warn "The management key stays between you and this wizard: it is used"
say "in-memory for two API calls, never written to disk, and you will"
say "delete it in the console at the end of this stage."
ask_secret XAI_MGMT_KEY "Paste the management key (input hidden):"
MGMT_URL="https://management-api.x.ai/v1/billing/teams/${TEAM_ID}/postpaid/spending-limits"
say "Current limits:"
curl -sS -H "Authorization: Bearer ${XAI_MGMT_KEY}" "$MGMT_URL" | sed 's/^/    /'
echo
note "Values are USD cents. 1000 = \$10.00/month."
ask XAI_LIMIT_CENTS "Desired soft spending limit in cents (e.g. 1000):"
curl -sS -X POST -H "Authorization: Bearer ${XAI_MGMT_KEY}" \
  -H 'Content-Type: application/json' \
  -d "{\"desiredSoftSpendingLimit\":{\"val\":\"${XAI_LIMIT_CENTS}\"}}" \
  "$MGMT_URL" | sed 's/^/    /'
echo
say "Re-reading limits to verify:"
LIMITS_AFTER=$(curl -sS -H "Authorization: Bearer ${XAI_MGMT_KEY}" "$MGMT_URL")
say "    ${LIMITS_AFTER}"
unset XAI_MGMT_KEY
XAI_TEAM_POSTPAID_LIMIT="${XAI_LIMIT_CENTS} USD cents/month (soft limit; GET after set: ${LIMITS_AFTER})"
write_env XAI_LIMIT_CENTS "$XAI_LIMIT_CENTS"
step "Now DELETE the management key in the console (Management Keys page)."
open_url "${TEAM_URL}/settings/management-keys"
pause "Press Enter once the management key is deleted."

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Verified zero prepaid balance"
say "A113 requires a verified zero-prepaid reading, recorded with its date."
say "(Adding a card sometimes grants promo credits: check, don't assume.)"
open_url "${TEAM_URL}/settings/billing"
step "Read the 'Credits' figure under Spend management."
ask XAI_PREPAID_READING "Credit balance exactly as shown (expect \$0.00):"
ask XAI_PREPAID_READING_DATE "Date of this reading (YYYY-MM-DD, today):"
write_env XAI_PREPAID_READING "$XAI_PREPAID_READING"
write_env XAI_PREPAID_READING_DATE "$XAI_PREPAID_READING_DATE"
if [[ "$XAI_PREPAID_READING" != "\$0.00" ]]; then
  warn "Balance is not \$0.00. A team carrying prepaid credit does not"
  say "satisfy A-5. Spend or remove the credit before qualification."
  confirm "Continue anyway (key can land now, qualification waits)?" || exit 1
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Create the API key (Claude never sees it)"
say "Create the key on the Patchyard Factory team so it is team-scoped."
open_url "${TEAM_URL}/api-keys"
step "Click 'Create API key'. Name it: factory-arbiter-seat"
step "Leave scope/permissions at chat defaults if asked."
step "Copy the key (starts 'xai-') to your clipboard, nothing else."
warn "Never paste the key into this wizard, a chat, or any file. It goes"
say "only into the root install command in the next stage."
ask XAI_KEY_CREATED_AT "Key creation timestamp as shown in the console:"
write_env XAI_KEY_CREATED_AT "$XAI_KEY_CREATED_AT"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Land the key on the control plane"
say "In a SEPARATE terminal, open a shell on the control plane (two hops):"
say ""
say "  ssh -t operator@example-controller sudo -n -u conductor \\"
say "    ssh -t conductor@factory.example.com"
say ""
say "Then on that host run:"
say ""
say "  sudo install -o root -g root -m 600 /dev/stdin /etc/patchyard/xai-seat.key"
say ""
step "Paste the key, press Enter, then Ctrl-D. Then close that shell."
note "The mint requires root:root 0600, a regular file, ASCII matching"
note "xai-[A-Za-z0-9]{16,8000}; a trailing newline is fine."
pause "Press Enter here once the key file is installed."
say "Verifying the file from here (two-hop ssh, metadata only)..."
if OUT=$(remote_root stat -c '%U:%G:%a %F %s' /etc/patchyard/xai-seat.key 2>&1); then
  say "  -> $OUT"
  if [[ "$OUT" == "root:root:600 regular file"* ]]; then
    say "${GREEN}✓ key file shape is correct${RESET}"
  else
    warn "Unexpected stat output: fix ownership/mode before continuing."
    confirm "Continue anyway?" || exit 1
  fi
else
  warn "Could not stat the key file: $OUT"
  confirm "Continue anyway?" || exit 1
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Smoke-test the mint path (no provider call, no spend)"
say "Running the issue's smoke test as root on the control plane. This"
say "exercises requester -> Polkit -> patchyard-xai-seat-mint@.service"
say "-> mint -> postconditions, end to end."
SMOKE_OUT=$(remote_root_stdin <<'SMOKE' 2>&1 || true
set -eu
ID="agent-$(uuidgen)"
systemd-run --uid=factory-manager --gid=factory --collect --wait --pipe --quiet \
  /bin/sh -c "mkdir -m 700 /run/patchyard-seats/$ID && \
    /usr/local/libexec/patchyard-request-xai-seat-bearer xAI /run/patchyard-seats/$ID/bearer && \
    stat -c '%U:%G:%a %s' /run/patchyard-seats/$ID/bearer && \
    rm -rf /run/patchyard-seats/$ID"
SMOKE
)
say "  -> ${SMOKE_OUT}"
if [[ "$SMOKE_OUT" == factory-manager:factory:600* ]]; then
  say "${GREEN}✓ mint path is live: expect 'factory-manager:factory:600 <bytes>'${RESET}"
  XAI_SMOKE_RESULT="pass: ${SMOKE_OUT}"
else
  warn "Smoke test did not produce 'factory-manager:factory:600 <bytes>'."
  say "Copy the output above to Claude to diagnose. The mint fails closed,"
  say "so nothing is broken: the arbiter seat just isn't live yet."
  XAI_SMOKE_RESULT="FAIL: ${SMOKE_OUT}"
fi
write_env XAI_SMOKE_RESULT "$XAI_SMOKE_RESULT"
pause

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Write the qualification record"
say "Writing the clause-3 facts (never the key) to ${RECORD_FILE}..."
cat > "$RECORD_FILE" <<RECORD
# xAI Factory team key — A113 clause 3 record (issue #358)

Recorded at credential creation for the qualification Result. The key
itself is deliberately not recorded anywhere.

- Team: ${TEAM_NAME} (id \`${TEAM_ID}\`), dedicated to the Factory
- Postpaid spending limit: ${XAI_TEAM_POSTPAID_LIMIT:-${XAI_LIMIT_CENTS:-unrecorded} USD cents/month (soft limit, set via management API)}
- Prepaid balance reading: ${XAI_PREPAID_READING} on ${XAI_PREPAID_READING_DATE}
- API key \`factory-arbiter-seat\` created: ${XAI_KEY_CREATED_AT}
- Key landed at \`/etc/patchyard/xai-seat.key\` (root:root 0600) and the
  mint smoke test ran the same day: ${XAI_SMOKE_RESULT}

Still open (issue #358 steps 4-6): the six A-5 qualification proofs, the
\`credential_qualified\` gate flip PR, and banking the first live envelope.
RECORD
say "${GREEN}✓ wrote ${RECORD_FILE}${RESET}"
note "Hand this file to the qualification session (issue #358 step 4)."

finish
